PAYLOAD = json.loads(r'''{
 "anchor.py": {
  "sha256": "7a8f0d21afc185f898ead19750168b6e7f2ba6a46d528aa645d75368eef8fcda",
  "text": "\"\"\"Duenna Stage 1 \u2014 external commitment anchor.\n\nThe hash chain in record.py proves order and content *as appended*\nand detects naive edits, but it cannot by itself detect a wholesale\nrewrite: an attacker (or a bug) can regenerate the whole record with\naltered content and re-chain it consistently from genesis, and the\nrecomputed chain verifies cleanly.\n\nThe anchor is the external commitment that catches that. After a\nclosure append, the record's head state \u2014 its head digest and its\nlength \u2014 is committed to an anchor file at a SEPARATE path, outside\nthe record being validated:\n\n    <record directory>/anchors/<record-name>.anchor.json\n\n(e.g. stage1/anchors/<record-name>.anchor.json for a record living\nin stage1/). The anchor is not supplied by the record: the writing\nfunction below takes ONLY head state values (a digest and a length)\nplus the destination path \u2014 it never opens or reads the record file.\nA validator can therefore compare a fresh-read record's head against\na commitment made independently of that record's own contents.\n\nHonesty boundary: an anchor that is missing or unreadable proves\nnothing either way. The validator reports that state as\nNOT_VERIFIED \u2014 distinct from PASS and from FAIL \u2014 and never rounds\nit up to verified.\n\nDesign references: ID-SYSTEM-DESIGN-DRAFT-V3.md (K9, G4),\nPROCESS-TREE-AND-PLAN.md v2, Stage 1 (step 4).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport os\n\nANCHOR_SUFFIX = \".anchor.json\"\n\n\ndef anchor_path_for(record_path: str, anchors_dir: str | None = None) -> str:\n    \"\"\"Return the anchor file path for the record at ``record_path``.\n\n    The anchor lives in an ``anchors`` directory beside the record\n    (or in ``anchors_dir`` when given) \u2014 always a separate path from\n    the record file itself.\n    \"\"\"\n    if anchors_dir is None:\n        anchors_dir = os.path.join(\n            os.path.dirname(os.path.abspath(record_path)), \"anchors\")\n    base = os.path.basename(record_path)\n    stem, _ext = os.path.splitext(base)\n    return os.path.join(anchors_dir, stem + ANCHOR_SUFFIX)\n\n\ndef write_anchor(head_digest: str, length: int, anchor_path: str) -> dict:\n    \"\"\"Commit head state values to the anchor file at ``anchor_path``.\n\n    This function's only inputs are the head state values\n    (``head_digest``, ``length``) and the destination path. It does\n    not read the record \u2014 the commitment is made from values handed\n    to it, so what lands in the anchor cannot be influenced by the\n    record file's contents at write time.\n\n    The write is flushed and fsynced. Returns the anchor dict.\n    \"\"\"\n    if not isinstance(head_digest, str) or not head_digest:\n        raise ValueError(\"head_digest must be a non-empty string\")\n    if not isinstance(length, int) or length < 0:\n        raise ValueError(\"length must be a non-negative int\")\n    anchor = {\"head_digest\": head_digest, \"length\": length}\n    directory = os.path.dirname(os.path.abspath(anchor_path))\n    os.makedirs(directory, exist_ok=True)\n    tmp_path = anchor_path + \".tmp\"\n    with open(tmp_path, \"w\", encoding=\"utf-8\") as f:\n        f.write(json.dumps(anchor, sort_keys=True) + \"\\n\")\n        f.flush()\n        os.fsync(f.fileno())\n    os.replace(tmp_path, anchor_path)\n    return anchor\n\n\ndef commit_record_head(record, anchors_dir: str | None = None) -> str:\n    \"\"\"Anchor the current head of ``record`` (an EventRecord).\n\n    Convenience wrapper for the post-closure step: reads the two\n    head state values off the record object and hands ONLY those\n    values to :func:`write_anchor`. Returns the anchor path.\n    \"\"\"\n    anchor_path = anchor_path_for(record.path, anchors_dir)\n    write_anchor(record.head_digest, record.length, anchor_path)\n    return anchor_path\n\n\ndef read_anchor(anchor_path: str) -> dict | None:\n    \"\"\"Read an anchor file. Returns its dict, or None when the file\n    is missing, unreadable, malformed, or lacks the head state\n    fields \u2014 the caller reports that state as NOT_VERIFIED, never\n    as a pass and never as a fail.\"\"\"\n    try:\n        with open(anchor_path, \"r\", encoding=\"utf-8\") as f:\n            data = json.load(f)\n    except (OSError, json.JSONDecodeError):\n        return None\n    if not isinstance(data, dict):\n        return None\n    if not isinstance(data.get(\"head_digest\"), str):\n        return None\n    if not isinstance(data.get(\"length\"), int):\n        return None\n    return {\"head_digest\": data[\"head_digest\"], \"length\": data[\"length\"]}\n"
 },
 "closure.py": {
  "sha256": "5b2d44d65302a9333ccd4e5a0bf0c81ddff76f68910ae53ac93a31619b2636f4",
  "text": "\"\"\"Duenna Stage 1 \u2014 closure writer.\n\nThe closure writer is invoked on EVERY controlled termination path\n(normal completion, known failure, early stop, exception). It appends\nexactly one CLOSURE event to the EventRecord, as the terminal event.\n\nThe CLOSURE event body carries the mandatory account (K9):\n\n- ``account`` \u2014 the failure-account section:\n    - ``failures``: a list of failure entries, each carrying\n      ``failure_id``, ``description`` and ``attribution`` (one of\n      SYSTEM / MODEL / INPUT / UNKNOWN), plus the ``authority`` under\n      which the attribution was minted.\n    - ``account_status``: ``COMPLETE`` or ``INCOMPLETE``. An account\n      that names any unknowns is INCOMPLETE, never COMPLETE.\n    - ``unknowns``: the things the account could not establish, named\n      explicitly (empty when the account is COMPLETE).\n    - ``authority``: the authority that minted the attributions.\n- ``endings`` \u2014 the three endings stated separately:\n  ``execution``, ``record`` and ``adjudication``. They are distinct\n  facts and are never collapsed into one status.\n- ``termination`` \u2014 which controlled termination path produced this\n  closure.\n\nTEST AUTHORITY FIXTURE: attributions in this harness are minted under\nthe clearly-marked TEST authority (``TEST_AUTHORITY`` below). That\nfixture exercises the attribution *shape* only; it settles nothing\nabout the production adjudicator authority (DR-13 remains open).\n\nDesign references: ID-SYSTEM-DESIGN-DRAFT-V3.md (K9, K10, G4),\nPROCESS-TREE-AND-PLAN.md v2, Stage 1.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom anchor import commit_record_head\n\n# Clearly-marked TEST authority fixture. Not a production authority.\nTEST_AUTHORITY = \"TEST-FIXTURE\"\nAUTHORITY = TEST_AUTHORITY\n\nVALID_ATTRIBUTIONS = (\"SYSTEM\", \"MODEL\", \"INPUT\", \"UNKNOWN\")\nVALID_ACCOUNT_STATUSES = (\"COMPLETE\", \"INCOMPLETE\")\n\n\ndef make_failure(failure_id: str, description: str,\n                 attribution: str | None = None,\n                 authority: str = TEST_AUTHORITY) -> dict:\n    \"\"\"Build one failure entry for a FAILURE event / closure account.\n\n    A missing attribution is recorded as UNKNOWN \u2014 the failure itself\n    is never omitted for lack of an attribution.\n    \"\"\"\n    if attribution is None:\n        attribution = \"UNKNOWN\"\n    if attribution not in VALID_ATTRIBUTIONS:\n        raise ValueError(f\"invalid attribution: {attribution!r}\")\n    return {\n        \"failure_id\": failure_id,\n        \"description\": description,\n        \"attribution\": attribution,\n        \"authority\": authority,\n    }\n\n\ndef build_closure_body(termination: str,\n                       failures: list[dict] | None = None,\n                       execution: str = \"COMPLETED\",\n                       adjudication: str = \"NOT_REQUIRED\",\n                       unknowns: list[str] | None = None,\n                       account_status: str | None = None,\n                       authority: str = TEST_AUTHORITY) -> dict:\n    \"\"\"Build the CLOSURE event body with its mandatory account.\n\n    If ``unknowns`` is non-empty the account is INCOMPLETE; asking for\n    COMPLETE while naming unknowns is refused, because a record must\n    not certify a completeness it simultaneously disclaims.\n    \"\"\"\n    failures = list(failures or [])\n    unknowns = list(unknowns or [])\n    for failure in failures:\n        if failure.get(\"attribution\") not in VALID_ATTRIBUTIONS:\n            raise ValueError(\n                f\"failure {failure.get('failure_id')!r} has invalid \"\n                f\"attribution: {failure.get('attribution')!r}\")\n    if account_status is None:\n        account_status = \"INCOMPLETE\" if unknowns else \"COMPLETE\"\n    if account_status not in VALID_ACCOUNT_STATUSES:\n        raise ValueError(f\"invalid account_status: {account_status!r}\")\n    if account_status == \"COMPLETE\" and unknowns:\n        raise ValueError(\n            \"account cannot declare COMPLETE while naming unknowns\")\n    return {\n        \"termination\": termination,\n        \"account\": {\n            \"failures\": failures,\n            \"account_status\": account_status,\n            \"unknowns\": unknowns,\n            \"authority\": authority,\n        },\n        \"endings\": {\n            \"execution\": execution,\n            \"record\": \"CLOSED\",\n            \"adjudication\": adjudication,\n        },\n        \"authority\": authority,\n    }\n\n\nclass ClosureWriter:\n    \"\"\"Appends the terminal CLOSURE event to an EventRecord.\n\n    After the closure append, the record's head state is committed\n    to the external anchor (anchor.py, Stage 1 step 4): immutability\n    evidence lives outside the chain.\n    \"\"\"\n\n    def __init__(self, record, authority: str = TEST_AUTHORITY,\n                 anchors_dir: str | None = None):\n        self.record = record\n        self.authority = authority\n        self.anchors_dir = anchors_dir\n\n    def close(self, termination: str,\n              failures: list[dict] | None = None,\n              execution: str = \"COMPLETED\",\n              adjudication: str = \"NOT_REQUIRED\",\n              unknowns: list[str] | None = None,\n              account_status: str | None = None) -> dict:\n        \"\"\"Append exactly one CLOSURE event; returns the event dict.\"\"\"\n        body = build_closure_body(\n            termination,\n            failures=failures,\n            execution=execution,\n            adjudication=adjudication,\n            unknowns=unknowns,\n            account_status=account_status,\n            authority=self.authority,\n        )\n        event = self.record.append(\"CLOSURE\", body)\n        # External commitment: anchor the new head state outside the\n        # record, so a wholesale re-chained rewrite is detectable.\n        commit_record_head(self.record, self.anchors_dir)\n        return event\n\n\ndef append_closure(record, termination: str, **kwargs) -> dict:\n    \"\"\"Convenience: append a CLOSURE event to ``record``.\"\"\"\n    return ClosureWriter(record).close(termination, **kwargs)\n"
 },
 "record.py": {
  "sha256": "9d6c6dd6c1f3ca060c883996588775f9314568b774348e9c0ab130ee8fabe3ea",
  "text": "\"\"\"Duenna Stage 1 \u2014 append-only event record.\n\nThe RECORD component's core: an append-only, hash-chained event log.\nEach event carries a sequence number, the digest of its predecessor, and its\nown digest over the canonical encoding of (seq, prev_digest, type, body).\n\nWhat the chain proves: the order and content of events as appended, and that\nnaive edits (rewriting or deleting a middle event) are detectable by\nrecomputation. What it does NOT prove: that the record was not wholesale\nrewritten and re-chained from genesis. That requires the external commitment\nanchor (Stage 1, step 4) \u2014 immutability evidence lives outside the chain.\n\nDesign references: ID-SYSTEM-DESIGN-DRAFT-V3.md (K9, P8),\nPROCESS-TREE-AND-PLAN.md v2, Stage 1.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nimport os\nfrom typing import Any, Iterator\n\nGENESIS = \"GENESIS\"\n\n\ndef _canonical(obj: Any) -> bytes:\n    return json.dumps(obj, sort_keys=True, separators=(\",\", \":\"),\n                      ensure_ascii=False).encode(\"utf-8\")\n\n\ndef _digest(seq: int, prev_digest: str, event_type: str, body: Any) -> str:\n    payload = {\"seq\": seq, \"prev\": prev_digest, \"type\": event_type, \"body\": body}\n    return hashlib.sha256(_canonical(payload)).hexdigest()\n\n\ndef _is_structurally_valid_event(ev) -> bool:\n    \"\"\"True iff ev is a dict with required fields of correct types.\"\"\"\n    if not isinstance(ev, dict):\n        return False\n    if not isinstance(ev.get(\"seq\"), int) or isinstance(ev.get(\"seq\"), bool):\n        return False\n    if not isinstance(ev.get(\"prev\"), str):\n        return False\n    if not isinstance(ev.get(\"type\"), str):\n        return False\n    if \"body\" not in ev:\n        return False\n    if not isinstance(ev.get(\"digest\"), str):\n        return False\n    return True\n\n\nclass EventRecord:\n    \"\"\"An append-only event record backed by a JSONL file.\n\n    Append is the only mutation. Appends are flushed and fsynced before the\n    event is considered recorded.\n    \"\"\"\n\n    def __init__(self, path: str):\n        self.path = path\n        self._seq = 0\n        self._head = GENESIS\n        if os.path.exists(path):\n            # C5 (Vane examination): reopening verifies the existing\n            # chain before permitting appends. A corrupted record\n            # refuses append -- constructing the record raises.\n            try:\n                events = list(self._iter_file())\n            except Exception as exc:\n                raise ValueError(\n                    f\"corrupted record: cannot parse existing record: {exc}\"\n                ) from exc\n            # Structural check: every event must be a dict with the\n            # required fields and types; malformed events are corruption.\n            for ev in events:\n                if not _is_structurally_valid_event(ev):\n                    raise ValueError(\n                        \"corrupted record: structurally malformed event: \"\n                        f\"{ev!r}\"\n                    )\n            ok, bad = verify_chain(events)\n            if not ok:\n                raise ValueError(\n                    f\"corrupted record: chain verification failed at seq {bad}\"\n                )\n            for ev in events:\n                self._seq = ev[\"seq\"]\n                self._head = ev[\"digest\"]\n\n    def _iter_file(self) -> Iterator[dict]:\n        with open(self.path, \"r\", encoding=\"utf-8\") as f:\n            for line in f:\n                line = line.strip()\n                if line:\n                    yield json.loads(line)\n\n    def append(self, event_type: str, body: Any) -> dict:\n        \"\"\"Append one event; returns the recorded event dict.\"\"\"\n        seq = self._seq + 1\n        digest = _digest(seq, self._head, event_type, body)\n        event = {\"seq\": seq, \"prev\": self._head, \"type\": event_type,\n                 \"body\": body, \"digest\": digest}\n        with open(self.path, \"a\", encoding=\"utf-8\") as f:\n            f.write(json.dumps(event, ensure_ascii=False) + \"\\n\")\n            f.flush()\n            os.fsync(f.fileno())\n        self._seq = seq\n        self._head = digest\n        return event\n\n    def read_all(self) -> list[dict]:\n        if not os.path.exists(self.path):\n            return []\n        return list(self._iter_file())\n\n    @property\n    def head_digest(self) -> str:\n        return self._head\n\n    @property\n    def length(self) -> int:\n        return self._seq\n\n\ndef verify_chain(events: list[dict]) -> tuple[bool, int | None]:\n    \"\"\"Recompute the chain over `events`.\n\n    Returns (True, None) if every event's seq, prev link and digest check\n    out in order; otherwise (False, seq_of_first_bad_event). An empty record\n    verifies. This detects edits and deletions; it cannot, by itself,\n    detect a wholesale rewrite that re-chains from genesis (see module\n    docstring \u2014 that is the external anchor's job).\n    \"\"\"\n    prev = GENESIS\n    expected_seq = 0\n    for ev in events:\n        expected_seq += 1\n        # C4: structurally malformed events yield a controlled failure,\n        # never a crash.\n        if not _is_structurally_valid_event(ev):\n            seq_val = ev.get(\"seq\") if isinstance(ev, dict) else None\n            return False, seq_val if isinstance(seq_val, int) else expected_seq\n        if ev.get(\"seq\") != expected_seq:\n            return False, ev.get(\"seq\", expected_seq)\n        if ev.get(\"prev\") != prev:\n            return False, ev[\"seq\"]\n        try:\n            want = _digest(ev[\"seq\"], ev[\"prev\"], ev[\"type\"], ev[\"body\"])\n        except Exception:\n            return False, ev[\"seq\"]\n        if ev.get(\"digest\") != want:\n            return False, ev[\"seq\"]\n        prev = ev[\"digest\"]\n    return True, None\n"
 },
 "runner.py": {
  "sha256": "c874f69b7847b7de074291b88fe5bd45c196d89008af7c99ee405556014cd084",
  "text": "\"\"\"Duenna Stage 1 \u2014 minimal scripted runner.\n\nA minimal runner that executes scripted scenarios on an EventRecord\n(record.py) and invokes the closure writer (closure.py) on EVERY\ncontrolled termination path:\n\n- normal completion\n- known failure\n- early stop\n- exception\n\nOn every path exactly one CLOSURE event is appended, as the last\nevent. Failures that occur during a scenario are also appended as\nFAILURE events (carrying their ``failure_id``) BEFORE closure, so a\nlater reconciliation (the validator, Stage 1 step 3) has something\nindependent of the closure account to reconcile against.\n\nAttributions minted here are made under the TEST authority fixture\ndeclared in closure.py (``authority=\"TEST-FIXTURE\"``). That fixture\nsettles nothing about DR-13.\n\nBoundary: controlled termination only. A hard kill of this process\nbefore its closure path executes is outside this harness's guarantee\nand is never claimed here.\n\nDesign references: ID-SYSTEM-DESIGN-DRAFT-V3.md (K9, G4),\nPROCESS-TREE-AND-PLAN.md v2, Stage 1.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom closure import ClosureWriter, TEST_AUTHORITY, make_failure\n\nSCENARIOS = (\"normal\", \"known_failure\", \"early_stop\", \"exception\")\n\n\nclass Runner:\n    \"\"\"Executes one scripted scenario against an EventRecord.\"\"\"\n\n    def __init__(self, record):\n        self.record = record\n        self.closure = ClosureWriter(record)\n        self.failures: list[dict] = []\n\n    # -- internals ---------------------------------------------------\n\n    def _record_failure(self, failure_id: str, description: str,\n                        attribution: str | None = None) -> dict:\n        \"\"\"Append a FAILURE event BEFORE closure and track it for the\n        closure account. Returns the failure entry.\"\"\"\n        failure = make_failure(failure_id, description, attribution,\n                               authority=TEST_AUTHORITY)\n        self.record.append(\"FAILURE\", dict(failure))\n        self.failures.append(failure)\n        return failure\n\n    def _started(self, scenario: str) -> None:\n        self.record.append(\"RUN_STARTED\", {\"scenario\": scenario})\n\n    # -- the four controlled termination paths ------------------------\n\n    def run_normal(self) -> dict:\n        \"\"\"Normal completion: no failures, COMPLETE empty account.\"\"\"\n        self._started(\"normal\")\n        self.record.append(\"STEP\", {\"n\": 1})\n        self.record.append(\"STEP\", {\"n\": 2})\n        return self.closure.close(\n            \"normal\",\n            failures=[],\n            execution=\"COMPLETED\",\n            adjudication=\"NOT_REQUIRED\",\n            unknowns=[],\n            account_status=\"COMPLETE\",\n        )\n\n    def run_known_failure(self) -> dict:\n        \"\"\"Known failure: the failure is recorded as a FAILURE event\n        and listed in the closure account with its attribution.\"\"\"\n        self._started(\"known_failure\")\n        self.record.append(\"STEP\", {\"n\": 1})\n        self._record_failure(\n            \"F-KNOWN-1\",\n            \"Scripted known failure\",\n            attribution=\"SYSTEM\",\n        )\n        return self.closure.close(\n            \"known_failure\",\n            failures=list(self.failures),\n            execution=\"FAILED\",\n            adjudication=\"ATTRIBUTED_UNDER_TEST_AUTHORITY\",\n            unknowns=[],\n            account_status=\"COMPLETE\",\n        )\n\n    def run_early_stop(self) -> dict:\n        \"\"\"Early stop: closure is appended; what the unexecuted steps\n        would have shown is named as UNKNOWN, so the account is\n        honestly INCOMPLETE.\"\"\"\n        self._started(\"early_stop\")\n        self.record.append(\"STEP\", {\"n\": 1})\n        self.record.append(\"STOP_REQUESTED\", {\"after_step\": 1})\n        return self.closure.close(\n            \"early_stop\",\n            failures=[],\n            execution=\"STOPPED_EARLY\",\n            adjudication=\"NOT_REQUIRED\",\n            unknowns=[\"outcome of steps not executed after early stop\"],\n            account_status=\"INCOMPLETE\",\n        )\n\n    def run_exception(self) -> dict:\n        \"\"\"Exception: a scenario step raises; the runner catches it,\n        records it as a FAILURE event (attribution UNKNOWN), and still\n        appends closure. The exception does not propagate.\"\"\"\n        self._started(\"exception\")\n        self.record.append(\"STEP\", {\"n\": 1})\n        try:\n            self._step_that_raises()\n        except RuntimeError as exc:\n            self._record_failure(\n                \"F-EXC-1\",\n                f\"Scripted exception: {exc}\",\n                attribution=\"UNKNOWN\",\n            )\n        return self.closure.close(\n            \"exception\",\n            failures=list(self.failures),\n            execution=\"EXCEPTION\",\n            adjudication=\"PENDING\",\n            unknowns=[],\n            account_status=\"COMPLETE\",\n        )\n\n    @staticmethod\n    def _step_that_raises() -> None:\n        raise RuntimeError(\"scripted exception in scenario step\")\n\n    # -- dispatch ------------------------------------------------------\n\n    def run(self, scenario: str) -> dict:\n        \"\"\"Run one named scenario; returns the CLOSURE event dict.\"\"\"\n        dispatch = {\n            \"normal\": self.run_normal,\n            \"known_failure\": self.run_known_failure,\n            \"early_stop\": self.run_early_stop,\n            \"exception\": self.run_exception,\n        }\n        if scenario not in dispatch:\n            raise ValueError(f\"unknown scenario: {scenario!r}\")\n        return dispatch[scenario]()\n\n\ndef run_scenario(record, scenario: str) -> dict:\n    \"\"\"Convenience: run ``scenario`` on ``record``, return CLOSURE.\"\"\"\n    return Runner(record).run(scenario)\n"
 },
 "validator.py": {
  "sha256": "1b56550ae9977d8927cdca8be943d660a9fd73c8699230a9180220c5b0f84adb",
  "text": "\"\"\"Duenna Stage 1 \u2014 independent closure validator.\n\nThe validator is INDEPENDENT of the writer: it reads ONLY the record\nfile fresh from disk (never the writer's in-memory objects) and\nreports G4's THREE INDEPENDENT RESULTS, never one collapsed boolean:\n\n(i)   ``terminal_record`` \u2014 exactly one CLOSURE event exists and it\n      is the last event in the record (C1, Vane examination). A parse\n      or structural failure makes this FAIL explicitly, because the\n      actual terminal state is then unknown (C4).\n(ii)  ``account_completeness`` \u2014 the closure account must first\n      satisfy its own documented schema (C6): ``account_status``\n      present and valid, ``unknowns`` present as a list of non-empty\n      strings, an INCOMPLETE account naming at least one unknown,\n      and the minting ``authority`` present on the account and on\n      each failure entry. A malformed account is rejected (FAIL),\n      never merely classified. The account is then reconciled\n      against the record itself: FAILURE events in the record and\n      failures in the closure account must match as exact sets with\n      non-empty unique failure_ids, required fields validated, and\n      description/attribution/authority matching the FAILURE event\n      as source of truth (C2; authority added by the hardening\n      follow-up \u2014 presence is not consistency). Wherever a value\n      must name something, a WHITESPACE-ONLY value (a string of\n      nothing but whitespace) is rejected: it is present, but it\n      names nothing. Each invalid-field diagnostic names the\n      offending field and preserves its exact original value in the\n      details for evidence. Omitted, extra, duplicate or altered entries\n      FAIL, whatever the account declares. An account that declares\n      COMPLETE while naming unknowns also FAILs. A well-formed\n      account whose status is INCOMPLETE is reported as INCOMPLETE.\n(iii) ``chain_validity`` \u2014 ``record.verify_chain`` recomputed over\n      the fresh-read events AND the fresh-read head compared against\n      the external anchor. Missing/unreadable anchor -> NOT_VERIFIED.\n\nStructurally malformed events (valid JSON with missing/mistyped\nfields) yield a structured FAIL, never a crash (C4).\n\nDesign references: ID-SYSTEM-DESIGN-DRAFT-V3.md (G4, G5, K9),\nPROCESS-TREE-AND-PLAN.md v2, Stage 1; Vane examination C1/C2/C4/C5\nand his corrected-implementation examination (C6).\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport os\nfrom collections import Counter\n\nfrom anchor import anchor_path_for, read_anchor\nfrom record import verify_chain, _is_structurally_valid_event\n\nPASS = \"PASS\"\nFAIL = \"FAIL\"\nINCOMPLETE = \"INCOMPLETE\"\nNOT_VERIFIED = \"NOT_VERIFIED\"\n\nVALID_ATTRIBUTIONS = (\"SYSTEM\", \"MODEL\", \"INPUT\", \"UNKNOWN\")\nVALID_ACCOUNT_STATUSES = (\"COMPLETE\", \"INCOMPLETE\")\n\n\ndef _read_events_fresh(path: str) -> tuple[list[dict], str | None]:\n    \"\"\"Read the record file fresh from disk.\n\n    Returns (events, parse_error). On a parse or structural error,\n    events holds the events read before the bad line and parse_error\n    names the problem; callers report structured FAIL rather than\n    guessing or crashing.\n    \"\"\"\n    events: list[dict] = []\n    if not os.path.exists(path):\n        return events, f\"record file not found: {path}\"\n    with open(path, \"r\", encoding=\"utf-8\") as f:\n        for lineno, line in enumerate(f, start=1):\n            line = line.strip()\n            if not line:\n                continue\n            try:\n                obj = json.loads(line)\n            except json.JSONDecodeError as exc:\n                return events, f\"line {lineno}: invalid JSON: {exc}\"\n            if not _is_structurally_valid_event(obj):\n                return events, (\n                    f\"line {lineno}: structurally malformed event: \"\n                    f\"missing or mistyped fields in {obj!r:.200}\"\n                )\n            events.append(obj)\n    return events, None\n\n\ndef _check_terminal_record(events: list[dict], parse_error: str | None = None) -> tuple[str, dict]:\n    # C4: parse/structural failure explicitly accounts here -- the\n    # terminal state is unknown, so it cannot PASS on a parsed prefix.\n    if parse_error is not None:\n        return FAIL, {\"closure_events\": len([ev for ev in events if isinstance(ev, dict) and ev.get(\"type\") == \"CLOSURE\"]),\n                      \"reason\": f\"parse failure: {parse_error}; terminal state unknown\",\n                      \"parse_error\": parse_error}\n    closures = [ev for ev in events if isinstance(ev, dict) and ev.get(\"type\") == \"CLOSURE\"]\n    if not closures:\n        return FAIL, {\"closure_events\": 0, \"reason\": \"no CLOSURE event\"}\n    # C1: exactly one CLOSURE required\n    if len(closures) != 1:\n        return FAIL, {\n            \"closure_events\": len(closures),\n            \"reason\": f\"expected exactly one CLOSURE event, found {len(closures)}\",\n        }\n    if not events or events[-1].get(\"type\") != \"CLOSURE\":\n        return FAIL, {\n            \"closure_events\": len(closures),\n            \"reason\": \"last event is not CLOSURE\",\n            \"last_type\": events[-1].get(\"type\") if events else None,\n        }\n    return PASS, {\"closure_events\": len(closures),\n                  \"closure_seq\": events[-1].get(\"seq\")}\n\n\ndef _duplicates(ids):\n    c = Counter(ids)\n    return sorted([k for k, v in c.items() if v > 1], key=lambda x: str(x))\n\n\ndef _has_content(value) -> bool:\n    \"\"\"Whether a value actually names something.\n\n    The term is WHITESPACE-ONLY (Ben's ruling, 2026-11-19, on Vane's\n    C6-examination observation): a string of nothing but whitespace\n    is present, and passes a plain non-empty check, but names\n    nothing \u2014 so wherever the schema requires a value to name\n    something (an unknown, an authority, a failure_id, a\n    description), a whitespace-only value is rejected. The check\n    never trims the value itself: the original is preserved in the\n    details for evidence.\n    \"\"\"\n    return isinstance(value, str) and bool(value.strip())\n\n\ndef _check_account_completeness(events: list[dict], parse_error: str | None = None) -> tuple[str, dict]:\n    if parse_error is not None:\n        return FAIL, {\"reason\": f\"parse failure: {parse_error}; account cannot be reconciled\",\n                      \"parse_error\": parse_error}\n    closures = [ev for ev in events if isinstance(ev, dict) and ev.get(\"type\") == \"CLOSURE\"]\n    if not closures:\n        return FAIL, {\"reason\": \"no CLOSURE event; no account to reconcile\"}\n    closure = closures[-1]\n    body = closure.get(\"body\") or {}\n    if not isinstance(body, dict):\n        return FAIL, {\"field\": \"body\", \"value\": body,\n                      \"reason\": \"CLOSURE body is not an object\"}\n    account = body.get(\"account\")\n    if not isinstance(account, dict):\n        return FAIL, {\"field\": \"account\", \"value\": account,\n                      \"reason\": \"CLOSURE event has no account section\"}\n\n    # C6 (Vane, corrected-implementation examination): the account\n    # itself must satisfy its documented schema (closure.py, K9),\n    # independently of whether its failures reconcile. C2 proves\n    # recorded failures are reconciled; C6 proves the account\n    # satisfies its declared contract. A malformed account is\n    # rejected below, never merely classified as incomplete.\n    schema_invalid = []\n    status_field = account.get(\"account_status\")\n    if status_field not in VALID_ACCOUNT_STATUSES:\n        schema_invalid.append(\n            {\"field\": \"account_status\", \"value\": status_field,\n             \"reason\": f\"account_status missing or invalid: {status_field!r}\"})\n    if \"unknowns\" not in account:\n        schema_invalid.append(\n            {\"field\": \"unknowns\", \"value\": account.get(\"unknowns\"),\n             \"reason\": \"account unknowns missing\"})\n    elif not isinstance(account.get(\"unknowns\"), list):\n        schema_invalid.append(\n            {\"field\": \"unknowns\", \"value\": account.get(\"unknowns\"),\n             \"reason\": f\"account unknowns is not a list: {account.get('unknowns')!r}\"})\n    else:\n        for u in account[\"unknowns\"]:\n            if not _has_content(u):\n                schema_invalid.append(\n                    {\"field\": \"unknowns\", \"value\": u,\n                     \"reason\": f\"account unknowns entry must name something (a non-empty string, not whitespace-only): {u!r}\"})\n        if status_field == \"INCOMPLETE\" and not account[\"unknowns\"]:\n            schema_invalid.append(\n                {\"field\": \"unknowns\", \"value\": account[\"unknowns\"],\n                 \"reason\": \"account declares INCOMPLETE without naming any unknowns\"})\n    account_authority = account.get(\"authority\")\n    if not _has_content(account_authority):\n        schema_invalid.append(\n            {\"field\": \"authority\", \"value\": account_authority,\n             \"reason\": \"account authority must name an authority (a non-empty string, not whitespace-only)\"})\n\n    # Collect record FAILURE events as source of truth\n    record_entries = []\n    record_failure_ids = []\n    record_by_id = {}\n    record_invalid = []\n    for ev in events:\n        if not isinstance(ev, dict) or ev.get(\"type\") != \"FAILURE\":\n            continue\n        b = ev.get(\"body\")\n        if not isinstance(b, dict):\n            record_invalid.append({\"field\": \"body\", \"value\": b,\n                                   \"reason\": \"FAILURE body is not an object\", \"body\": b})\n            record_failure_ids.append(None)\n            continue\n        fid = b.get(\"failure_id\")\n        record_failure_ids.append(fid)\n        record_entries.append(b)\n        # Validate required fields (whitespace-only names nothing).\n        # Every diagnostic names the offending field and preserves\n        # its exact original value for examination.\n        if not _has_content(fid):\n            record_invalid.append({\"failure_id\": fid, \"field\": \"failure_id\", \"value\": fid, \"reason\": \"record failure_id must be a string naming something (non-empty, not whitespace-only)\"})\n        if not _has_content(b.get(\"description\")):\n            record_invalid.append({\"failure_id\": fid, \"field\": \"description\", \"value\": b.get(\"description\"), \"reason\": \"record description must be a string naming something (non-empty, not whitespace-only)\"})\n        if b.get(\"attribution\") not in VALID_ATTRIBUTIONS:\n            record_invalid.append({\"failure_id\": fid, \"field\": \"attribution\", \"value\": b.get(\"attribution\"), \"reason\": f\"record attribution invalid: {b.get('attribution')!r}\"})\n        if not _has_content(b.get(\"authority\")):\n            record_invalid.append({\"failure_id\": fid, \"field\": \"authority\", \"value\": b.get(\"authority\"), \"reason\": \"record failure authority must be a string naming an authority (non-empty, not whitespace-only)\"})\n        if isinstance(fid, str) and fid:\n            # Keep first as source of truth for altered comparison; duplicates handled separately\n            if fid not in record_by_id:\n                record_by_id[fid] = b\n\n    account_failures = account.get(\"failures\")\n    if not isinstance(account_failures, list):\n        return FAIL, {\"field\": \"failures\", \"value\": account_failures,\n                      \"reason\": \"account has no failures list\",\n                      \"record_failure_ids\": record_failure_ids}\n    account_failure_ids = []\n    account_by_id = {}\n    account_invalid = []\n    for f in account_failures:\n        if not isinstance(f, dict):\n            account_invalid.append({\"field\": \"entry\", \"value\": f,\n                                    \"reason\": \"account failure entry is not an object\", \"entry\": f})\n            account_failure_ids.append(None)\n            continue\n        fid = f.get(\"failure_id\")\n        account_failure_ids.append(fid)\n        # Every diagnostic names the offending field and preserves\n        # its exact original value for examination.\n        if not _has_content(fid):\n            account_invalid.append({\"failure_id\": fid, \"field\": \"failure_id\", \"value\": fid, \"reason\": \"account failure_id must be a string naming something (non-empty, not whitespace-only)\"})\n        if not _has_content(f.get(\"description\")):\n            account_invalid.append({\"failure_id\": fid, \"field\": \"description\", \"value\": f.get(\"description\"), \"reason\": \"account description must be a string naming something (non-empty, not whitespace-only)\"})\n        if f.get(\"attribution\") not in VALID_ATTRIBUTIONS:\n            account_invalid.append({\"failure_id\": fid, \"field\": \"attribution\", \"value\": f.get(\"attribution\"), \"reason\": f\"account attribution invalid: {f.get('attribution')!r}\"})\n        # C6: the documented schema requires the minting authority\n        # on each account failure entry as well.\n        if not _has_content(f.get(\"authority\")):\n            account_invalid.append({\"failure_id\": fid, \"field\": \"authority\", \"value\": f.get(\"authority\"), \"reason\": \"account failure authority must be a string naming an authority (non-empty, not whitespace-only)\"})\n        if isinstance(fid, str) and fid and fid not in account_by_id:\n            account_by_id[fid] = f\n\n    duplicate_record = _duplicates([x for x in record_failure_ids if isinstance(x, str) and x])\n    duplicate_account = _duplicates([x for x in account_failure_ids if isinstance(x, str) and x])\n\n    # Exact-set reconciliation\n    record_set = set([x for x in record_failure_ids if isinstance(x, str) and x])\n    account_set = set([x for x in account_failure_ids if isinstance(x, str) and x])\n    omitted = [fid for fid in record_failure_ids if fid not in account_failure_ids]\n    # Preserve original omitted semantics (list in record order) for regression fixture,\n    # but also compute set-based omitted/extra\n    omitted_set = sorted(record_set - account_set)\n    extra = sorted(account_set - record_set)\n    extra_failure_ids = extra\n\n    # Altered: description/attribution/authority differ from the\n    # FAILURE event as source of truth. Authority joined the\n    # comparison in the hardening follow-up (Vane's C6-examination\n    # observation: presence is not consistency \u2014 an account entry\n    # minted under a different authority than its source event is\n    # an altered entry, even when both values are present).\n    altered = []\n    altered_details = []\n    for fid in sorted(record_set & account_set):\n        rec = record_by_id.get(fid, {})\n        acc = account_by_id.get(fid, {})\n        differing_fields = [\n            field for field in (\"description\", \"attribution\", \"authority\")\n            if rec.get(field) != acc.get(field)\n        ]\n        if differing_fields:\n            altered.append(fid)\n            altered_details.append({\"failure_id\": fid, \"fields\": differing_fields, \"record\": {\"description\": rec.get(\"description\"), \"attribution\": rec.get(\"attribution\"), \"authority\": rec.get(\"authority\")}, \"account\": {\"description\": acc.get(\"description\"), \"attribution\": acc.get(\"attribution\"), \"authority\": acc.get(\"authority\")}})\n\n    details = {\n        \"record_failure_ids\": record_failure_ids,\n        \"account_failure_ids\": account_failure_ids,\n        \"omitted_failure_ids\": omitted,\n        \"extra_failure_ids\": extra_failure_ids,\n        \"duplicate_record_failure_ids\": duplicate_record,\n        \"duplicate_account_failure_ids\": duplicate_account,\n        \"altered_failure_ids\": altered,\n        \"altered_details\": altered_details,\n        \"record_invalid\": record_invalid,\n        \"account_invalid\": account_invalid,\n        \"account_schema_invalid\": schema_invalid,\n        \"account_status\": account.get(\"account_status\"),\n        \"unknowns\": account.get(\"unknowns\"),\n    }\n\n    if schema_invalid:\n        details[\"reason\"] = \"closure account fails its documented schema (C6)\"\n        return FAIL, details\n    if record_invalid:\n        details[\"reason\"] = \"record FAILURE event(s) have invalid required fields\"\n        return FAIL, details\n    if account_invalid:\n        details[\"reason\"] = \"account failure entr(ies) have invalid required fields\"\n        return FAIL, details\n    if duplicate_record:\n        details[\"reason\"] = \"duplicate failure_id(s) in record\"\n        return FAIL, details\n    if duplicate_account:\n        details[\"reason\"] = \"duplicate failure_id(s) in account\"\n        return FAIL, details\n    if omitted:\n        details[\"reason\"] = \"FAILURE event(s) missing from closure account\"\n        return FAIL, details\n    if extra:\n        details[\"reason\"] = \"account contains failure(s) not in record\"\n        return FAIL, details\n    if altered:\n        details[\"reason\"] = \"account failure description/attribution/authority differs from record FAILURE event\"\n        return FAIL, details\n\n    status = account.get(\"account_status\")\n    unknowns = account.get(\"unknowns\") or []\n    if status == \"COMPLETE\" and unknowns:\n        details[\"reason\"] = \"account declares COMPLETE while naming unknowns\"\n        return FAIL, details\n    if status == \"INCOMPLETE\":\n        details[\"reason\"] = \"account declares itself INCOMPLETE\"\n        return INCOMPLETE, details\n    if status != \"COMPLETE\":\n        details[\"reason\"] = f\"unrecognised account_status: {status!r}\"\n        return FAIL, details\n    return PASS, details\n\n\ndef _check_chain_validity(events: list[dict],\n                          parse_error: str | None,\n                          anchor_path: str) -> tuple[str, dict]:\n    if parse_error is not None:\n        return FAIL, {\"reason\": parse_error, \"anchor_path\": anchor_path}\n    try:\n        ok, bad_seq = verify_chain(events)\n    except Exception as exc:\n        return FAIL, {\"reason\": f\"chain verification crashed: {exc}\", \"anchor_path\": anchor_path}\n    if not ok:\n        return FAIL, {\"first_bad_seq\": bad_seq, \"anchor_path\": anchor_path}\n    anchor = read_anchor(anchor_path)\n    if anchor is None:\n        return NOT_VERIFIED, {\n            \"reason\": \"anchor file missing or unreadable; integrity \"\n                      \"not verified\",\n            \"anchor_path\": anchor_path,\n            \"events_checked\": len(events),\n        }\n    head_digest = events[-1].get(\"digest\") if events else \"GENESIS\"\n    head = {\"head_digest\": head_digest, \"length\": len(events)}\n    if head[\"head_digest\"] != anchor[\"head_digest\"] or \\\n            head[\"length\"] != anchor[\"length\"]:\n        return FAIL, {\n            \"reason\": \"head state does not match external anchor \"\n                      \"(possible wholesale re-chained rewrite)\",\n            \"anchor_path\": anchor_path,\n            \"record_head\": head,\n            \"anchor\": anchor,\n        }\n    return PASS, {\"events_checked\": len(events),\n                  \"anchor_path\": anchor_path, \"anchor\": anchor}\n\n\ndef validate_record(path: str, anchor_path: str | None = None,\n                    anchors_dir: str | None = None) -> dict:\n    \"\"\"Validate the record file at ``path``, fresh from disk.\n\n    Returns a dict with G4's three independent results \u2014\n    ``terminal_record``, ``account_completeness`` and\n    ``chain_validity`` \u2014 each one of PASS / FAIL (account completeness\n    may also be INCOMPLETE; chain validity may also be\n    NOT_VERIFIED when the external anchor is unavailable), plus a\n    ``details`` dict per dimension.\n    \"\"\"\n    if anchor_path is None:\n        anchor_path = anchor_path_for(path, anchors_dir)\n    events, parse_error = _read_events_fresh(path)\n    terminal, terminal_details = _check_terminal_record(events, parse_error)\n    account, account_details = _check_account_completeness(events, parse_error)\n    chain, chain_details = _check_chain_validity(events, parse_error,\n                                                 anchor_path)\n    return {\n        \"terminal_record\": terminal,\n        \"account_completeness\": account,\n        \"chain_validity\": chain,\n        \"details\": {\n            \"terminal_record\": terminal_details,\n            \"account_completeness\": account_details,\n            \"chain_validity\": chain_details,\n        },\n    }\n\n\nclass RecordValidator:\n    \"\"\"Thin class wrapper around :func:`validate_record`.\"\"\"\n\n    def __init__(self, path: str, anchor_path: str | None = None,\n                 anchors_dir: str | None = None):\n        self.path = path\n        self.anchor_path = anchor_path\n        self.anchors_dir = anchors_dir\n\n    def validate(self) -> dict:\n        return validate_record(self.path, anchor_path=self.anchor_path,\n                               anchors_dir=self.anchors_dir)\n"
 },
 "tests/test_anchor.py": {
  "sha256": "cb37edeb9f236b22eebcd9a141d2efa3db35de3c516c245bfc95b27e28ab43a4",
  "text": "\"\"\"Stage 1, step 4 \u2014 tests for the external commitment anchor.\n\nThe anchor commits the record's head digest + length to a file at a\nSEPARATE path, written from head state values only. The validator's\nchain_validity result (iii) becomes: chain valid AND head matches\nthe anchor. Missing/unreadable anchor -> NOT_VERIFIED (distinct\nfrom PASS and from FAIL).\n\nRun: python3 -m unittest discover -s ~/workspace/duenna-fix/stage1/tests -v\n\"\"\"\n\nimport json\nimport os\nimport sys\nimport tempfile\nimport unittest\n\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \"..\"))\nfrom anchor import (  # noqa: E402\n    anchor_path_for, commit_record_head, read_anchor, write_anchor)\nfrom record import EventRecord, verify_chain  # noqa: E402\nfrom runner import Runner  # noqa: E402\nfrom validator import validate_record  # noqa: E402\n\n\nclass TestAnchor(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.path = os.path.join(self.tmp.name, \"record.jsonl\")\n\n    def tearDown(self):\n        self.tmp.cleanup()\n\n    def _run(self, scenario=\"normal\", path=None):\n        path = path or self.path\n        record = EventRecord(path)\n        Runner(record).run(scenario)\n        return record\n\n    def test_normal_closed_record_verifies(self):\n        record = self._run(\"normal\")\n        # The closure append committed an anchor at a separate path.\n        anchor_path = anchor_path_for(self.path)\n        self.assertNotEqual(os.path.abspath(anchor_path),\n                            os.path.abspath(self.path))\n        self.assertTrue(os.path.exists(anchor_path))\n        anchor = read_anchor(anchor_path)\n        self.assertEqual(anchor[\"head_digest\"], record.head_digest)\n        self.assertEqual(anchor[\"length\"], record.length)\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n        self.assertEqual(\n            result[\"details\"][\"chain_validity\"][\"anchor\"][\"head_digest\"],\n            record.head_digest)\n\n    def test_write_anchor_takes_only_head_state_values(self):\n        anchor_path = os.path.join(self.tmp.name, \"anchors\", \"x.anchor.json\")\n        written = write_anchor(\"deadbeef\" * 8, 5, anchor_path)\n        self.assertEqual(written, {\"head_digest\": \"deadbeef\" * 8,\n                                   \"length\": 5})\n        self.assertEqual(read_anchor(anchor_path), written)\n        with self.assertRaises(ValueError):\n            write_anchor(\"\", 5, anchor_path)\n        with self.assertRaises(ValueError):\n            write_anchor(\"abc\", -1, anchor_path)\n\n    def test_wholesale_rechained_rewrite_caught_by_anchor_mismatch(self):\n        record = self._run(\"normal\")\n        original = record.read_all()\n        anchor_path = anchor_path_for(self.path)\n        self.assertTrue(os.path.exists(anchor_path))\n\n        # Wholesale rewrite: regenerate a record with the same event\n        # types/bodies but different content in one event, re-chained\n        # consistently from genesis, at the same path.\n        os.remove(self.path)\n        rewritten = EventRecord(self.path)\n        for ev in original:\n            body = ev[\"body\"]\n            if ev[\"type\"] == \"STEP\":\n                body = dict(body, n=999)  # altered content\n            rewritten.append(ev[\"type\"], body)\n\n        # The rewritten chain is internally valid \u2014 recomputation\n        # alone cannot catch this. The anchor must.\n        events = rewritten.read_all()\n        ok, _ = verify_chain(events)\n        self.assertTrue(ok)\n        self.assertEqual(rewritten.length, record.length)\n        self.assertNotEqual(rewritten.head_digest, record.head_digest)\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"chain_validity\"], \"FAIL\")\n        self.assertIn(\"anchor\", result[\"details\"][\"chain_validity\"]\n                      [\"reason\"])\n        # The other dimensions are reported independently.\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n\n    def test_missing_anchor_yields_not_verified(self):\n        # Build a closed record by hand-appending events, bypassing\n        # ClosureWriter so NO anchor is ever committed.\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"normal\"})\n        from closure import build_closure_body\n        record.append(\"CLOSURE\", build_closure_body(\"normal\"))\n        self.assertFalse(os.path.exists(anchor_path_for(self.path)))\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"chain_validity\"], \"NOT_VERIFIED\")\n        self.assertNotEqual(result[\"chain_validity\"], \"PASS\")\n        self.assertNotEqual(result[\"chain_validity\"], \"FAIL\")\n        # The other dimensions still report on their own merits.\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n\n    def test_deleted_anchor_after_closure_yields_not_verified(self):\n        self._run(\"normal\")\n        anchor_path = anchor_path_for(self.path)\n        self.assertTrue(os.path.exists(anchor_path))\n        os.remove(anchor_path)\n        result = validate_record(self.path)\n        self.assertEqual(result[\"chain_validity\"], \"NOT_VERIFIED\")\n\n    def test_unreadable_anchor_yields_not_verified(self):\n        self._run(\"normal\")\n        anchor_path = anchor_path_for(self.path)\n        with open(anchor_path, \"w\", encoding=\"utf-8\") as f:\n            f.write(\"{not json\")\n        self.assertIsNone(read_anchor(anchor_path))\n        result = validate_record(self.path)\n        self.assertEqual(result[\"chain_validity\"], \"NOT_VERIFIED\")\n\n    def test_commit_record_head_uses_current_head_values(self):\n        record = self._run(\"known_failure\")\n        anchor_path = commit_record_head(record)\n        with open(anchor_path, \"r\", encoding=\"utf-8\") as f:\n            data = json.load(f)\n        self.assertEqual(data[\"head_digest\"], record.head_digest)\n        self.assertEqual(data[\"length\"], record.length)\n        result = validate_record(self.path)\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 },
 "tests/test_c6_account_schema.py": {
  "sha256": "ff5d9b383f09c06d165a0e7c01791760c0c9799cfe1bfa427f3605129aea40e7",
  "text": "\"\"\"Stage 1 \u2014 Vane C6: mandatory closure-account schema validation.\n\nC6 is preserved as its own finding (Vane, corrected-implementation\nexamination, 2026-11-19), NOT folded into C2: C2 proves that recorded\nfailures are reconciled; C6 proves that the account itself satisfies\nits declared contract (closure.py, K9). A malformed account must be\nREJECTED by the independent validator (account_completeness FAIL),\nnever merely classified as incomplete.\n\nEach malformed account is built with the real writer, mutated before\nthe CLOSURE event is appended (so the hash chain stays valid and the\nvalidator's account result is the thing on trial), and anchored.\n\"\"\"\n\nimport os\nimport sys\nimport tempfile\nimport unittest\n\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \"..\"))\nfrom anchor import anchor_path_for, write_anchor  # noqa: E402\nfrom closure import build_closure_body, make_failure  # noqa: E402\nfrom record import EventRecord  # noqa: E402\nfrom validator import validate_record  # noqa: E402\n\n\nclass TestC6AccountSchema(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.path = os.path.join(self.tmp.name, \"record.jsonl\")\n\n    def tearDown(self):\n        self.tmp.cleanup()\n\n    def _validate_with_body(self, body, failures=()):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"c6\"})\n        for f in failures:\n            record.append(\"FAILURE\", f)\n        record.append(\"CLOSURE\", body)\n        write_anchor(record.head_digest, record.length,\n                     anchor_path_for(self.path))\n        return validate_record(self.path)\n\n    def _account_result(self, body, failures=()):\n        result = self._validate_with_body(body, failures)\n        return result[\"account_completeness\"], result[\"details\"][\"account_completeness\"]\n\n    # Vane test 1: INCOMPLETE with missing unknowns -> reject.\n    def test_c6_incomplete_missing_unknowns(self):\n        body = build_closure_body(\n            \"early_stop\", unknowns=[\"steps not executed\"],\n            account_status=\"INCOMPLETE\")\n        del body[\"account\"][\"unknowns\"]\n        status, details = self._account_result(body)\n        self.assertEqual(status, \"FAIL\")\n        self.assertTrue(details[\"account_schema_invalid\"])\n\n    # Vane test 2: INCOMPLETE with an empty unknowns list -> reject.\n    # An account may not claim incompleteness while naming nothing.\n    def test_c6_incomplete_empty_unknowns(self):\n        body = build_closure_body(\n            \"early_stop\", unknowns=[\"steps not executed\"],\n            account_status=\"INCOMPLETE\")\n        body[\"account\"][\"unknowns\"] = []\n        status, details = self._account_result(body)\n        self.assertEqual(status, \"FAIL\")\n        self.assertTrue(details[\"account_schema_invalid\"])\n\n    # Vane test 3a: COMPLETE with missing unknowns -> reject.\n    def test_c6_complete_missing_unknowns(self):\n        body = build_closure_body(\"normal\")\n        del body[\"account\"][\"unknowns\"]\n        status, details = self._account_result(body)\n        self.assertEqual(status, \"FAIL\")\n        self.assertTrue(details[\"account_schema_invalid\"])\n\n    # Vane test 3b: COMPLETE with wrongly typed unknowns -> reject.\n    def test_c6_complete_unknowns_wrong_type(self):\n        body = build_closure_body(\"normal\")\n        body[\"account\"][\"unknowns\"] = \"none\"\n        status, details = self._account_result(body)\n        self.assertEqual(status, \"FAIL\")\n        self.assertTrue(details[\"account_schema_invalid\"])\n\n    # Vane test 4a: unknowns containing an empty entry -> reject.\n    def test_c6_unknowns_empty_string_entry(self):\n        body = build_closure_body(\n            \"early_stop\", unknowns=[\"\"], account_status=\"INCOMPLETE\")\n        status, details = self._account_result(body)\n        self.assertEqual(status, \"FAIL\")\n        self.assertTrue(details[\"account_schema_invalid\"])\n\n    # Vane test 4b: unknowns containing a non-string entry -> reject.\n    def test_c6_unknowns_non_string_entry(self):\n        body = build_closure_body(\n            \"early_stop\", unknowns=[42], account_status=\"INCOMPLETE\")\n        status, details = self._account_result(body)\n        self.assertEqual(status, \"FAIL\")\n        self.assertTrue(details[\"account_schema_invalid\"])\n\n    # Vane test 5a: the documented schema requires the minting\n    # authority on the account; missing -> reject.\n    def test_c6_missing_account_authority(self):\n        body = build_closure_body(\"normal\")\n        del body[\"account\"][\"authority\"]\n        status, details = self._account_result(body)\n        self.assertEqual(status, \"FAIL\")\n        self.assertTrue(details[\"account_schema_invalid\"])\n\n    # Vane test 5b: the documented schema requires the authority on\n    # each account failure entry; missing -> reject, even though the\n    # entry otherwise reconciles with the record's FAILURE event.\n    def test_c6_missing_failure_entry_authority(self):\n        record_failure = make_failure(\"F-1\", \"widget jammed\", \"SYSTEM\")\n        account_entry = dict(record_failure)\n        del account_entry[\"authority\"]\n        body = build_closure_body(\"known_failure\", failures=[account_entry])\n        status, details = self._account_result(body, failures=[record_failure])\n        self.assertEqual(status, \"FAIL\")\n        self.assertTrue(details[\"account_invalid\"])\n\n    # Control: a well-formed INCOMPLETE account (the writer's real\n    # early-stop shape) is still classified INCOMPLETE, not rejected.\n    def test_c6_wellformed_incomplete_still_incomplete(self):\n        body = build_closure_body(\n            \"early_stop\", unknowns=[\"steps not executed\"],\n            account_status=\"INCOMPLETE\")\n        status, details = self._account_result(body)\n        self.assertEqual(status, \"INCOMPLETE\")\n        self.assertEqual(details[\"account_schema_invalid\"], [])\n\n    # Control: a well-formed COMPLETE account still passes.\n    def test_c6_wellformed_complete_still_passes(self):\n        body = build_closure_body(\"normal\")\n        status, details = self._account_result(body)\n        self.assertEqual(status, \"PASS\")\n        self.assertEqual(details[\"account_schema_invalid\"], [])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 },
 "tests/test_closure.py": {
  "sha256": "b13906a3b10b70ad0e7591117e4ff26d19188ba38fc144777ffac25dcb942631",
  "text": "\"\"\"Stage 1, step 2 \u2014 tests for the closure writer + runner.\n\nRun: python3 -m unittest discover -s ~/workspace/duenna-fix/stage1/tests -v\n\"\"\"\n\nimport os\nimport sys\nimport tempfile\nimport unittest\n\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \"..\"))\nfrom record import EventRecord  # noqa: E402\nfrom runner import Runner, SCENARIOS  # noqa: E402\n\n\nclass TestClosureRunner(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.path = os.path.join(self.tmp.name, \"record.jsonl\")\n\n    def tearDown(self):\n        self.tmp.cleanup()\n\n    def _run(self, scenario):\n        record = EventRecord(self.path)\n        Runner(record).run(scenario)\n        return record.read_all()\n\n    def test_each_path_yields_exactly_one_closure_as_last_event(self):\n        for scenario in SCENARIOS:\n            with self.subTest(scenario=scenario):\n                # Fresh record per scenario.\n                path = os.path.join(self.tmp.name, f\"{scenario}.jsonl\")\n                record = EventRecord(path)\n                Runner(record).run(scenario)\n                events = record.read_all()\n                closures = [e for e in events if e[\"type\"] == \"CLOSURE\"]\n                self.assertEqual(len(closures), 1)\n                self.assertEqual(events[-1][\"type\"], \"CLOSURE\")\n\n    def test_known_failure_account_lists_failure_with_attribution(self):\n        events = self._run(\"known_failure\")\n        closure = events[-1]\n        failures = closure[\"body\"][\"account\"][\"failures\"]\n        self.assertEqual(len(failures), 1)\n        self.assertEqual(failures[0][\"failure_id\"], \"F-KNOWN-1\")\n        self.assertEqual(failures[0][\"attribution\"], \"SYSTEM\")\n        self.assertIn(\"description\", failures[0])\n        self.assertEqual(closure[\"body\"][\"account\"][\"authority\"],\n                         \"TEST-FIXTURE\")\n        self.assertEqual(failures[0][\"authority\"], \"TEST-FIXTURE\")\n\n    def test_known_failure_also_appended_as_failure_event_before_closure(self):\n        events = self._run(\"known_failure\")\n        types = [e[\"type\"] for e in events]\n        self.assertIn(\"FAILURE\", types)\n        failure_idx = types.index(\"FAILURE\")\n        closure_idx = types.index(\"CLOSURE\")\n        self.assertLess(failure_idx, closure_idx)\n        failure_event = events[failure_idx]\n        self.assertEqual(failure_event[\"body\"][\"failure_id\"], \"F-KNOWN-1\")\n\n    def test_exception_path_still_closes(self):\n        events = self._run(\"exception\")\n        self.assertEqual(events[-1][\"type\"], \"CLOSURE\")\n        closures = [e for e in events if e[\"type\"] == \"CLOSURE\"]\n        self.assertEqual(len(closures), 1)\n        failures = events[-1][\"body\"][\"account\"][\"failures\"]\n        self.assertEqual(len(failures), 1)\n        self.assertEqual(failures[0][\"failure_id\"], \"F-EXC-1\")\n        self.assertEqual(failures[0][\"attribution\"], \"UNKNOWN\")\n\n    def test_clean_path_account_complete_with_empty_failures(self):\n        events = self._run(\"normal\")\n        account = events[-1][\"body\"][\"account\"]\n        self.assertEqual(account[\"account_status\"], \"COMPLETE\")\n        self.assertEqual(account[\"failures\"], [])\n        self.assertEqual(account[\"unknowns\"], [])\n\n    def test_closure_states_three_endings_separately(self):\n        for scenario in SCENARIOS:\n            with self.subTest(scenario=scenario):\n                path = os.path.join(self.tmp.name, f\"end-{scenario}.jsonl\")\n                record = EventRecord(path)\n                Runner(record).run(scenario)\n                endings = record.read_all()[-1][\"body\"][\"endings\"]\n                self.assertEqual(\n                    set(endings), {\"execution\", \"record\", \"adjudication\"})\n                self.assertEqual(endings[\"record\"], \"CLOSED\")\n\n    def test_early_stop_account_incomplete_with_unknowns_named(self):\n        events = self._run(\"early_stop\")\n        account = events[-1][\"body\"][\"account\"]\n        self.assertEqual(account[\"account_status\"], \"INCOMPLETE\")\n        self.assertTrue(account[\"unknowns\"])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 },
 "tests/test_record.py": {
  "sha256": "2fd10bf8aa0abf2588a0d4664a3bb3c9bf42ccfab62f868aec2d7ad042f20db4",
  "text": "\"\"\"Stage 1, step 1 \u2014 tests for the append-only event record.\n\nRun: python3 -m unittest discover -s ~/workspace/duenna-fix/stage1/tests -v\n\"\"\"\n\nimport json\nimport os\nimport sys\nimport tempfile\nimport unittest\n\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \"..\"))\nfrom record import EventRecord, verify_chain  # noqa: E402\n\n\nclass TestEventRecord(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.path = os.path.join(self.tmp.name, \"record.jsonl\")\n\n    def tearDown(self):\n        self.tmp.cleanup()\n\n    def test_append_assigns_sequence_and_chains(self):\n        r = EventRecord(self.path)\n        e1 = r.append(\"RUN_STARTED\", {\"run\": \"r1\"})\n        e2 = r.append(\"STEP\", {\"n\": 1})\n        self.assertEqual((e1[\"seq\"], e2[\"seq\"]), (1, 2))\n        self.assertEqual(e1[\"prev\"], \"GENESIS\")\n        self.assertEqual(e2[\"prev\"], e1[\"digest\"])\n        self.assertEqual(r.head_digest, e2[\"digest\"])\n        self.assertEqual(r.length, 2)\n\n    def test_reopen_continues_from_head(self):\n        r = EventRecord(self.path)\n        r.append(\"A\", {})\n        r.append(\"B\", {})\n        r2 = EventRecord(self.path)\n        e3 = r2.append(\"C\", {})\n        self.assertEqual(e3[\"seq\"], 3)\n        ok, bad = verify_chain(r2.read_all())\n        self.assertTrue(ok, f\"chain failed at {bad}\")\n\n    def test_clean_record_verifies(self):\n        r = EventRecord(self.path)\n        for i in range(5):\n            r.append(\"STEP\", {\"n\": i})\n        ok, bad = verify_chain(r.read_all())\n        self.assertTrue(ok)\n        self.assertIsNone(bad)\n\n    def test_empty_record_verifies(self):\n        self.assertEqual(verify_chain([]), (True, None))\n\n    def test_rewritten_middle_event_detected(self):\n        r = EventRecord(self.path)\n        for i in range(4):\n            r.append(\"STEP\", {\"n\": i})\n        events = r.read_all()\n        events[1][\"body\"] = {\"n\": 999}  # silent edit, digest left stale\n        ok, bad = verify_chain(events)\n        self.assertFalse(ok)\n        self.assertEqual(bad, 2)\n\n    def test_deleted_event_detected(self):\n        r = EventRecord(self.path)\n        for i in range(4):\n            r.append(\"STEP\", {\"n\": i})\n        events = r.read_all()\n        del events[1]\n        ok, _ = verify_chain(events)\n        self.assertFalse(ok)\n\n    def test_record_file_is_append_only_jsonl(self):\n        r = EventRecord(self.path)\n        r.append(\"A\", {\"x\": 1})\n        r.append(\"B\", {\"x\": 2})\n        with open(self.path, encoding=\"utf-8\") as f:\n            lines = [json.loads(l) for l in f if l.strip()]\n        self.assertEqual([l[\"type\"] for l in lines], [\"A\", \"B\"])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 },
 "tests/test_stage1_cases.py": {
  "sha256": "b8e33e9b0adfd32397af0a4aa592c19b4dfffcc5a4ac84fba81ed328d8446548",
  "text": "\"\"\"Stage 1, step 5 \u2014 sabotage suite: the examiner's eight cases.\n\nEach case runs end-to-end against the real record / runner /\nvalidator / anchor (no mocks of the components under examination),\nas its own named test, so every case is reported separately by name:\n\n(1) normal completion\n(2) known failure accounted with attribution\n(3) early stop closes with known/unknown stated\n(4) exception path appends closure\n(5) missing failure account (closure body without the account\n    section \u2014 constructed directly) still leaves a terminal\n    record; validator reports account incompleteness\n(6) missing attribution recorded as UNKNOWN, failure not omitted\n(7) rewritten chain detected (anchor)\n(8) anchor unavailable -> NOT_VERIFIED, never passed\n(9) the omitted-known-failure case from step 3, restated end-to-end\n\nRun: python3 -m unittest discover -s ~/workspace/duenna-fix/stage1/tests -v\n     (or: python3 -m unittest test_stage1_cases -v from tests/)\n\"\"\"\n\nimport os\nimport sys\nimport tempfile\nimport unittest\n\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \"..\"))\nfrom anchor import anchor_path_for, write_anchor  # noqa: E402\nfrom closure import (  # noqa: E402\n    ClosureWriter, build_closure_body, make_failure)\nfrom record import EventRecord, verify_chain  # noqa: E402\nfrom runner import Runner  # noqa: E402\nfrom validator import validate_record  # noqa: E402\n\n\nclass TestStage1Cases(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.path = os.path.join(self.tmp.name, \"record.jsonl\")\n\n    def tearDown(self):\n        self.tmp.cleanup()\n\n    def _run(self, scenario, path=None):\n        path = path or self.path\n        record = EventRecord(path)\n        Runner(record).run(scenario)\n        return record\n\n    # -- (1) normal completion --------------------------------------\n\n    def test_case1_normal_completion(self):\n        record = self._run(\"normal\")\n        events = record.read_all()\n        closures = [e for e in events if e[\"type\"] == \"CLOSURE\"]\n        self.assertEqual(len(closures), 1)\n        self.assertEqual(events[-1][\"type\"], \"CLOSURE\")\n        account = events[-1][\"body\"][\"account\"]\n        self.assertEqual(account[\"account_status\"], \"COMPLETE\")\n        self.assertEqual(account[\"failures\"], [])\n        self.assertEqual(account[\"unknowns\"], [])\n        endings = events[-1][\"body\"][\"endings\"]\n        self.assertEqual(set(endings),\n                         {\"execution\", \"record\", \"adjudication\"})\n        self.assertEqual(endings[\"execution\"], \"COMPLETED\")\n        self.assertEqual(endings[\"record\"], \"CLOSED\")\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    # -- (2) known failure accounted with attribution ----------------\n\n    def test_case2_known_failure_accounted_with_attribution(self):\n        record = self._run(\"known_failure\")\n        events = record.read_all()\n        types = [e[\"type\"] for e in events]\n        # The failure is in the record itself, BEFORE closure, so\n        # reconciliation has something independent to check against.\n        self.assertIn(\"FAILURE\", types)\n        self.assertLess(types.index(\"FAILURE\"), types.index(\"CLOSURE\"))\n        failure_event = events[types.index(\"FAILURE\")]\n        self.assertEqual(failure_event[\"body\"][\"failure_id\"], \"F-KNOWN-1\")\n\n        account = events[-1][\"body\"][\"account\"]\n        self.assertEqual(len(account[\"failures\"]), 1)\n        entry = account[\"failures\"][0]\n        self.assertEqual(entry[\"failure_id\"], \"F-KNOWN-1\")\n        self.assertEqual(entry[\"attribution\"], \"SYSTEM\")\n        self.assertTrue(entry[\"description\"])\n        self.assertEqual(entry[\"authority\"], \"TEST-FIXTURE\")\n        self.assertEqual(account[\"authority\"], \"TEST-FIXTURE\")\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    # -- (3) early stop closes with known/unknown stated -------------\n\n    def test_case3_early_stop_closes_with_known_unknown_stated(self):\n        record = self._run(\"early_stop\")\n        events = record.read_all()\n        self.assertEqual(events[-1][\"type\"], \"CLOSURE\")\n        body = events[-1][\"body\"]\n        self.assertEqual(body[\"termination\"], \"early_stop\")\n        self.assertEqual(body[\"endings\"][\"execution\"], \"STOPPED_EARLY\")\n        # What is known and what is unknown are stated separately:\n        # the account is honestly INCOMPLETE and names its unknowns.\n        account = body[\"account\"]\n        self.assertEqual(account[\"account_status\"], \"INCOMPLETE\")\n        self.assertTrue(account[\"unknowns\"])\n        self.assertIn(\"steps not executed\", account[\"unknowns\"][0])\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        # INCOMPLETE is a distinct, honest result \u2014 not a pass.\n        self.assertEqual(result[\"account_completeness\"], \"INCOMPLETE\")\n        self.assertNotEqual(result[\"account_completeness\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    # -- (4) exception path appends closure --------------------------\n\n    def test_case4_exception_path_appends_closure(self):\n        record = self._run(\"exception\")\n        events = record.read_all()\n        closures = [e for e in events if e[\"type\"] == \"CLOSURE\"]\n        self.assertEqual(len(closures), 1)\n        self.assertEqual(events[-1][\"type\"], \"CLOSURE\")\n        self.assertEqual(events[-1][\"body\"][\"endings\"][\"execution\"],\n                         \"EXCEPTION\")\n        # The exception was recorded as a FAILURE event before closure.\n        failure_ids = [(e[\"body\"] or {}).get(\"failure_id\")\n                       for e in events if e[\"type\"] == \"FAILURE\"]\n        self.assertEqual(failure_ids, [\"F-EXC-1\"])\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    # -- (5) missing failure account ---------------------------------\n\n    def test_case5_missing_failure_account(self):\n        # Construct a CLOSURE body WITHOUT the account section,\n        # directly \u2014 the closure writer always writes an account,\n        # so this record is built by hand.\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"missing_account\"})\n        failure = make_failure(\"F-NOACCT-1\", \"Failure with no account\",\n                               attribution=\"SYSTEM\")\n        record.append(\"FAILURE\", dict(failure))\n        body_without_account = {\n            \"termination\": \"known_failure\",\n            \"endings\": {\"execution\": \"FAILED\", \"record\": \"CLOSED\",\n                        \"adjudication\": \"NOT_REQUIRED\"},\n            \"authority\": \"TEST-FIXTURE\",\n        }\n        self.assertNotIn(\"account\", body_without_account)\n        record.append(\"CLOSURE\", body_without_account)\n        # Hand-appended closure bypasses ClosureWriter, so commit\n        # the external anchor explicitly for the chain check.\n        write_anchor(record.head_digest, record.length,\n                     anchor_path_for(self.path))\n\n        events = record.read_all()\n        # The record is still terminal: a CLOSURE exists and is last.\n        self.assertEqual(events[-1][\"type\"], \"CLOSURE\")\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        # ...but the validator reports account incompleteness.\n        self.assertEqual(result[\"account_completeness\"], \"FAIL\")\n        self.assertIn(\"no account\",\n                      result[\"details\"][\"account_completeness\"][\"reason\"])\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    # -- (6) missing attribution recorded as UNKNOWN -----------------\n\n    def test_case6_missing_attribution_recorded_as_unknown(self):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"missing_attribution\"})\n        # No attribution supplied: make_failure records UNKNOWN and\n        # the failure itself is NOT omitted.\n        failure = make_failure(\"F-NOATTR-1\",\n                               \"Failure with no attribution supplied\")\n        self.assertEqual(failure[\"attribution\"], \"UNKNOWN\")\n        record.append(\"FAILURE\", dict(failure))\n        ClosureWriter(record).close(\n            \"known_failure\",\n            failures=[failure],\n            execution=\"FAILED\",\n            adjudication=\"ATTRIBUTED_UNDER_TEST_AUTHORITY\",\n            unknowns=[],\n            account_status=\"COMPLETE\",\n        )\n\n        events = record.read_all()\n        failure_events = [e for e in events if e[\"type\"] == \"FAILURE\"]\n        self.assertEqual(len(failure_events), 1)\n        self.assertEqual(failure_events[0][\"body\"][\"attribution\"],\n                         \"UNKNOWN\")\n        account_failures = events[-1][\"body\"][\"account\"][\"failures\"]\n        self.assertEqual([f[\"failure_id\"] for f in account_failures],\n                         [\"F-NOATTR-1\"])\n        self.assertEqual(account_failures[0][\"attribution\"], \"UNKNOWN\")\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        # Reconciliation finds the failure accounted \u2014 not omitted.\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n        self.assertEqual(\n            result[\"details\"][\"account_completeness\"]\n            [\"omitted_failure_ids\"], [])\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    # -- (7) rewritten chain detected (anchor) -----------------------\n\n    def test_case7_rewritten_chain_detected_by_anchor(self):\n        record = self._run(\"normal\")\n        original = record.read_all()\n        anchor_path = anchor_path_for(self.path)\n        self.assertTrue(os.path.exists(anchor_path))\n\n        # Wholesale rewrite: same event types/bodies except altered\n        # content in one event, re-chained consistently from genesis\n        # at the same path. The chain alone verifies cleanly.\n        os.remove(self.path)\n        rewritten = EventRecord(self.path)\n        for ev in original:\n            body = ev[\"body\"]\n            if ev[\"type\"] == \"STEP\":\n                body = dict(body, n=999)\n            rewritten.append(ev[\"type\"], body)\n        ok, _ = verify_chain(rewritten.read_all())\n        self.assertTrue(ok)\n        self.assertEqual(rewritten.length, record.length)\n        self.assertNotEqual(rewritten.head_digest, record.head_digest)\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"chain_validity\"], \"FAIL\")\n        self.assertIn(\"anchor\",\n                      result[\"details\"][\"chain_validity\"][\"reason\"])\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n\n    # -- (8) anchor unavailable -> NOT_VERIFIED, never passed --------\n\n    def test_case8_anchor_unavailable_not_verified_never_passed(self):\n        # Closed record built by hand-appending events, bypassing\n        # ClosureWriter so NO anchor is ever committed.\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"normal\"})\n        record.append(\"CLOSURE\", build_closure_body(\"normal\"))\n        self.assertFalse(os.path.exists(anchor_path_for(self.path)))\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"chain_validity\"], \"NOT_VERIFIED\")\n        self.assertNotEqual(result[\"chain_validity\"], \"PASS\")\n        self.assertNotEqual(result[\"chain_validity\"], \"FAIL\")\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n\n        # Same result when an anchor existed but was then removed.\n        path2 = os.path.join(self.tmp.name, \"record2.jsonl\")\n        self._run(\"normal\", path=path2)\n        anchor2 = anchor_path_for(path2)\n        self.assertTrue(os.path.exists(anchor2))\n        os.remove(anchor2)\n        result2 = validate_record(path2)\n        self.assertEqual(result2[\"chain_validity\"], \"NOT_VERIFIED\")\n        self.assertNotEqual(result2[\"chain_validity\"], \"PASS\")\n\n    # -- (9) omitted known failure, restated end-to-end --------------\n\n    def test_case9_omitted_known_failure_fails_account_completeness(self):\n        # The record contains two FAILURE events; the closure\n        # account lists only one while declaring COMPLETE.\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"omitted_failure\"})\n        f1 = make_failure(\"F-OMIT-1\", \"First known failure\",\n                          attribution=\"SYSTEM\")\n        f2 = make_failure(\"F-OMIT-2\", \"Second known failure\",\n                          attribution=\"MODEL\")\n        record.append(\"FAILURE\", dict(f1))\n        record.append(\"FAILURE\", dict(f2))\n        body = build_closure_body(\n            \"known_failure\",\n            failures=[f1],  # F-OMIT-2 silently omitted\n            execution=\"FAILED\",\n            adjudication=\"ATTRIBUTED_UNDER_TEST_AUTHORITY\",\n            unknowns=[],\n            account_status=\"COMPLETE\",\n        )\n        record.append(\"CLOSURE\", body)\n        write_anchor(record.head_digest, record.length,\n                     anchor_path_for(self.path))\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"FAIL\")\n        self.assertEqual(\n            result[\"details\"][\"account_completeness\"]\n            [\"omitted_failure_ids\"], [\"F-OMIT-2\"])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 },
 "tests/test_validator.py": {
  "sha256": "9a9f143b4bdc4bc830621f3824589bcec97ee9b6e7e1ecac53e70a9257f3300a",
  "text": "\"\"\"Stage 1, step 3 \u2014 tests for the independent validator.\n\nThe validator reads ONLY the record file fresh from disk and returns\nG4's three independent results: terminal_record, account_completeness,\nchain_validity.\n\nRun: python3 -m unittest discover -s ~/workspace/duenna-fix/stage1/tests -v\n\"\"\"\n\nimport json\nimport os\nimport sys\nimport tempfile\nimport unittest\n\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \"..\"))\nfrom anchor import anchor_path_for, write_anchor  # noqa: E402\nfrom closure import build_closure_body, make_failure  # noqa: E402\nfrom record import EventRecord  # noqa: E402\nfrom runner import Runner  # noqa: E402\nfrom validator import validate_record  # noqa: E402\n\n\nclass TestValidator(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.path = os.path.join(self.tmp.name, \"record.jsonl\")\n\n    def tearDown(self):\n        self.tmp.cleanup()\n\n    def _run(self, scenario, path=None):\n        path = path or self.path\n        record = EventRecord(path)\n        Runner(record).run(scenario)\n        return path\n\n    def test_clean_run_passes_all_three(self):\n        result = validate_record(self._run(\"normal\"))\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    def test_known_failure_run_passes_all_three(self):\n        result = validate_record(self._run(\"known_failure\"))\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    def test_early_stop_account_reported_incomplete_not_pass(self):\n        result = validate_record(self._run(\"early_stop\"))\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"INCOMPLETE\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    def test_omitted_failure_fails_account_completeness(self):\n        # THE OMITTED-KNOWN-FAILURE CASE: the record contains two\n        # FAILURE events; the closure account lists only one while\n        # declaring COMPLETE. The chain is valid and the closure is\n        # terminal \u2014 only reconciliation against the record itself\n        # can catch the omission, and it MUST fail (ii).\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"omitted_failure\"})\n        f1 = make_failure(\"F-OMIT-1\", \"First known failure\",\n                          attribution=\"SYSTEM\")\n        f2 = make_failure(\"F-OMIT-2\", \"Second known failure\",\n                          attribution=\"MODEL\")\n        record.append(\"FAILURE\", dict(f1))\n        record.append(\"FAILURE\", dict(f2))\n        body = build_closure_body(\n            \"known_failure\",\n            failures=[f1],  # F-OMIT-2 silently omitted\n            execution=\"FAILED\",\n            adjudication=\"ATTRIBUTED_UNDER_TEST_AUTHORITY\",\n            unknowns=[],\n            account_status=\"COMPLETE\",\n        )\n        record.append(\"CLOSURE\", body)\n        # Hand-appended closure bypasses ClosureWriter, so commit the\n        # external anchor explicitly (step 4) for the chain check.\n        write_anchor(record.head_digest, record.length,\n                     anchor_path_for(self.path))\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"FAIL\")\n        self.assertEqual(\n            result[\"details\"][\"account_completeness\"]\n            [\"omitted_failure_ids\"],\n            [\"F-OMIT-2\"],\n        )\n\n    def test_record_with_no_closure_fails_terminal_record(self):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"normal\"})\n        record.append(\"STEP\", {\"n\": 1})\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"FAIL\")\n        self.assertEqual(result[\"account_completeness\"], \"FAIL\")\n\n    def test_edited_middle_event_body_fails_chain_validity(self):\n        self._run(\"normal\")\n        with open(self.path, \"r\", encoding=\"utf-8\") as f:\n            lines = f.readlines()\n        self.assertGreaterEqual(len(lines), 3)\n        middle = json.loads(lines[1])\n        middle[\"body\"] = {\"n\": 999, \"tampered\": True}\n        lines[1] = json.dumps(middle, ensure_ascii=False) + \"\\n\"\n        with open(self.path, \"w\", encoding=\"utf-8\") as f:\n            f.writelines(lines)\n\n        result = validate_record(self.path)\n        self.assertEqual(result[\"chain_validity\"], \"FAIL\")\n        # The other dimensions are reported independently.\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n\n    def test_complete_declared_with_unknowns_fails_account(self):\n        # Hand-constructed (closure.py refuses to build this): an\n        # account declaring COMPLETE while naming unknowns.\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"hand\"})\n        body = {\n            \"termination\": \"hand\",\n            \"account\": {\n                \"failures\": [],\n                \"account_status\": \"COMPLETE\",\n                \"unknowns\": [\"something not established\"],\n                \"authority\": \"TEST-FIXTURE\",\n            },\n            \"endings\": {\"execution\": \"COMPLETED\", \"record\": \"CLOSED\",\n                        \"adjudication\": \"NOT_REQUIRED\"},\n            \"authority\": \"TEST-FIXTURE\",\n        }\n        record.append(\"CLOSURE\", body)\n        # Hand-appended closure bypasses ClosureWriter, so commit the\n        # external anchor explicitly (step 4) for the chain check.\n        write_anchor(record.head_digest, record.length,\n                     anchor_path_for(self.path))\n        result = validate_record(self.path)\n        self.assertEqual(result[\"account_completeness\"], \"FAIL\")\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    def test_validator_reads_fresh_from_disk(self):\n        # Validate, then rewrite the file behind the writer's back:\n        # the next validation must reflect the file, not any\n        # in-memory state.\n        self._run(\"normal\")\n        first = validate_record(self.path)\n        self.assertEqual(first[\"terminal_record\"], \"PASS\")\n        with open(self.path, \"w\", encoding=\"utf-8\") as f:\n            f.write(\"\")\n        second = validate_record(self.path)\n        self.assertEqual(second[\"terminal_record\"], \"FAIL\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 },
 "tests/test_vane_hardening.py": {
  "sha256": "9166939c2c8cea6494e7c46d5b24aacdfddb3bd335478ee98c809827160cade4",
  "text": "\"\"\"Stage 1 \u2014 hardening follow-up to Vane's C6 examination.\n\nTwo additional observations from his examination of the C6 round\n(2026-11-19), applied as a small follow-up at Ben's tap \u2014 they do\nnot erase or relabel C6:\n\n1. AUTHORITY CONSISTENCY. Presence is not consistency: the\n   reconciliation must compare each account failure entry's\n   authority against the corresponding FAILURE event, as it\n   already compares description and attribution.\n\n2. WHITESPACE-ONLY VALUES. The term is WHITESPACE-ONLY (Ben's\n   ruling): a string of nothing but whitespace is present, and\n   passes a plain non-empty check, but names nothing. Wherever a\n   value must name something \u2014 an unknown, an authority, a\n   failure_id, a description \u2014 a whitespace-only value is\n   rejected. The original value is preserved untrimmed in the\n   validator's details for evidence.\n\nFinal evidence-detail adjustment (Vane's hardening examination):\neach invalid-field diagnostic must name the offending field and\ncarry its exact original value, on both the record and account\nsides. The account-side failure_id and description cases are\nexercised explicitly below.\n\"\"\"\n\nimport os\nimport sys\nimport tempfile\nimport unittest\n\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \"..\"))\nfrom anchor import anchor_path_for, write_anchor  # noqa: E402\nfrom closure import build_closure_body, make_failure  # noqa: E402\nfrom record import EventRecord  # noqa: E402\nfrom validator import validate_record  # noqa: E402\n\n\nclass TestVaneHardening(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.path = os.path.join(self.tmp.name, \"record.jsonl\")\n\n    def tearDown(self):\n        self.tmp.cleanup()\n\n    def _validate(self, body, failures=()):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"hardening\"})\n        for f in failures:\n            record.append(\"FAILURE\", f)\n        record.append(\"CLOSURE\", body)\n        write_anchor(record.head_digest, record.length,\n                     anchor_path_for(self.path))\n        return validate_record(self.path)\n\n    def _account(self, body, failures=()):\n        result = self._validate(body, failures)\n        return result[\"account_completeness\"], result[\"details\"][\"account_completeness\"]\n\n    def _diagnostic(self, entries, field):\n        return next(entry for entry in entries if entry.get(\"field\") == field)\n\n    # --- 1. Authority consistency ---------------------------------\n    # Account entry minted under a different authority than its\n    # source FAILURE event: both present, both non-empty \u2014 and the\n    # entry is still altered. Presence is not consistency.\n    def test_authority_mismatch_is_altered(self):\n        record_failure = make_failure(\"F-1\", \"widget jammed\", \"SYSTEM\")\n        account_entry = dict(record_failure)\n        account_entry[\"authority\"] = \"OTHER-AUTHORITY\"\n        body = build_closure_body(\"known_failure\", failures=[account_entry])\n        status, details = self._account(body, failures=[record_failure])\n        self.assertEqual(status, \"FAIL\")\n        self.assertEqual(details[\"altered_failure_ids\"], [\"F-1\"])\n        self.assertEqual(\n            details[\"altered_details\"][0][\"record\"][\"authority\"],\n            \"TEST-FIXTURE\")\n        self.assertEqual(\n            details[\"altered_details\"][0][\"account\"][\"authority\"],\n            \"OTHER-AUTHORITY\")\n\n    # Control: matching authority reconciles clean.\n    def test_authority_match_passes(self):\n        record_failure = make_failure(\"F-1\", \"widget jammed\", \"SYSTEM\")\n        body = build_closure_body(\n            \"known_failure\", failures=[dict(record_failure)])\n        status, _ = self._account(body, failures=[record_failure])\n        self.assertEqual(status, \"PASS\")\n\n    # --- 2. Whitespace-only values --------------------------------\n    def test_whitespace_only_unknown_rejected(self):\n        body = build_closure_body(\n            \"early_stop\", unknowns=[\"   \"], account_status=\"INCOMPLETE\")\n        status, details = self._account(body)\n        self.assertEqual(status, \"FAIL\")\n        self.assertTrue(details[\"account_schema_invalid\"])\n        # The original value is preserved for evidence, untrimmed.\n        self.assertEqual(details[\"unknowns\"], [\"   \"])\n\n    def test_whitespace_only_account_authority_rejected(self):\n        body = build_closure_body(\"normal\")\n        body[\"account\"][\"authority\"] = \"  \"\n        status, details = self._account(body)\n        self.assertEqual(status, \"FAIL\")\n        diagnostic = self._diagnostic(\n            details[\"account_schema_invalid\"], \"authority\")\n        self.assertEqual(diagnostic[\"value\"], \"  \")\n\n    def test_whitespace_only_entry_authority_rejected(self):\n        record_failure = make_failure(\"F-1\", \"widget jammed\", \"SYSTEM\")\n        account_entry = dict(record_failure)\n        account_entry[\"authority\"] = \" \"\n        body = build_closure_body(\"known_failure\", failures=[account_entry])\n        status, details = self._account(body, failures=[record_failure])\n        self.assertEqual(status, \"FAIL\")\n        diagnostic = self._diagnostic(details[\"account_invalid\"], \"authority\")\n        self.assertEqual(diagnostic[\"failure_id\"], \"F-1\")\n        self.assertEqual(diagnostic[\"value\"], \" \")\n\n    def test_whitespace_only_description_rejected(self):\n        record_failure = make_failure(\"F-1\", \"   \", \"SYSTEM\")\n        body = build_closure_body(\n            \"known_failure\", failures=[dict(record_failure)])\n        status, details = self._account(body, failures=[record_failure])\n        self.assertEqual(status, \"FAIL\")\n        diagnostic = self._diagnostic(details[\"record_invalid\"], \"description\")\n        self.assertEqual(diagnostic[\"failure_id\"], \"F-1\")\n        self.assertEqual(diagnostic[\"value\"], \"   \")\n\n    def test_whitespace_only_failure_id_rejected(self):\n        record_failure = make_failure(\"  \", \"widget jammed\", \"SYSTEM\")\n        body = build_closure_body(\n            \"known_failure\", failures=[dict(record_failure)])\n        status, details = self._account(body, failures=[record_failure])\n        self.assertEqual(status, \"FAIL\")\n        diagnostic = self._diagnostic(details[\"record_invalid\"], \"failure_id\")\n        self.assertEqual(diagnostic[\"value\"], \"  \")\n\n    def test_whitespace_only_account_failure_id_rejected(self):\n        record_failure = make_failure(\"F-1\", \"widget jammed\", \"SYSTEM\")\n        account_entry = dict(record_failure)\n        account_entry[\"failure_id\"] = \" \\t\"\n        body = build_closure_body(\"known_failure\", failures=[account_entry])\n        status, details = self._account(body, failures=[record_failure])\n        self.assertEqual(status, \"FAIL\")\n        diagnostic = self._diagnostic(details[\"account_invalid\"], \"failure_id\")\n        self.assertEqual(diagnostic[\"value\"], \" \\t\")\n\n    def test_whitespace_only_account_description_rejected(self):\n        record_failure = make_failure(\"F-1\", \"widget jammed\", \"SYSTEM\")\n        account_entry = dict(record_failure)\n        account_entry[\"description\"] = \" \\n\"\n        body = build_closure_body(\"known_failure\", failures=[account_entry])\n        status, details = self._account(body, failures=[record_failure])\n        self.assertEqual(status, \"FAIL\")\n        diagnostic = self._diagnostic(details[\"account_invalid\"], \"description\")\n        self.assertEqual(diagnostic[\"failure_id\"], \"F-1\")\n        self.assertEqual(diagnostic[\"value\"], \" \\n\")\n\n    # Control: content with surrounding whitespace names something \u2014\n    # it is accepted, and the recorded value is preserved as-is.\n    def test_padded_content_accepted_and_preserved(self):\n        body = build_closure_body(\n            \"early_stop\", unknowns=[\"  steps not executed  \"],\n            account_status=\"INCOMPLETE\")\n        status, details = self._account(body)\n        self.assertEqual(status, \"INCOMPLETE\")\n        self.assertEqual(details[\"unknowns\"], [\"  steps not executed  \"])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 },
 "tests/test_vane_sabotage.py": {
  "sha256": "7892f6e067e1d1ba4fce9a78b57217840fc06de28785919641b1302e6d18f199",
  "text": "\"\"\"Stage 1, step S7 \u2014 Vane sabotage tests S1-S8.\n\nNamed tests matching Vane's corrections C1, C2, C4, C5, plus the\nC3/S8 boundary demonstration. Each runs against the real\nrecord / runner / validator / anchor.\n\nS1 duplicate terminal closure -> terminal FAIL (C1)\nS2 duplicate failure ID in record -> account FAIL (C2)\nS3 duplicate account failure ID -> account FAIL (C2)\nS4 extra fabricated account failure -> account FAIL (C2)\nS5 altered failure description/attribution -> account FAIL (C2)\nS6 structurally malformed event -> chain FAIL, no crash (C4)\nS7 corrupted record reopened for append -> append refused (C5)\nS8 record and anchor both rewritten -> boundary demonstration (C3)\n\"\"\"\n\nimport json\nimport os\nimport sys\nimport tempfile\nimport unittest\n\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), \"..\"))\nfrom anchor import anchor_path_for, write_anchor  # noqa: E402\nfrom closure import build_closure_body, make_failure  # noqa: E402\nfrom record import EventRecord, verify_chain  # noqa: E402\nfrom runner import Runner  # noqa: E402\nfrom validator import validate_record  # noqa: E402\n\n\nclass TestVaneSabotage(unittest.TestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.path = os.path.join(self.tmp.name, \"record.jsonl\")\n\n    def tearDown(self):\n        self.tmp.cleanup()\n\n    def _anchor(self, record, path=None):\n        path = path or self.path\n        write_anchor(record.head_digest, record.length, anchor_path_for(path))\n\n    # S1\n    def test_s1_duplicate_terminal_closure(self):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"dup_closure\"})\n        record.append(\"CLOSURE\", build_closure_body(\"normal\"))\n        record.append(\"CLOSURE\", build_closure_body(\"normal\"))\n        self._anchor(record)\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"FAIL\")\n        self.assertEqual(result[\"details\"][\"terminal_record\"][\"closure_events\"], 2)\n\n    def test_s1b_two_closures_with_event_afterward(self):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"dup_closure_after\"})\n        record.append(\"CLOSURE\", build_closure_body(\"normal\"))\n        record.append(\"CLOSURE\", build_closure_body(\"normal\"))\n        record.append(\"STEP\", {\"n\": 99})\n        self._anchor(record)\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"FAIL\")\n\n    def test_s1c_closure_followed_by_continuation(self):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"closure_cont\"})\n        record.append(\"CLOSURE\", build_closure_body(\"normal\"))\n        record.append(\"STEP\", {\"n\": 1})\n        self._anchor(record)\n        result = validate_record(self.path)\n        self.assertEqual(result[\"terminal_record\"], \"FAIL\")\n\n    # S2\n    def test_s2_duplicate_failure_id_in_record(self):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"dup_record_id\"})\n        f = make_failure(\"F-DUP-1\", \"Duplicate failure\", attribution=\"SYSTEM\")\n        record.append(\"FAILURE\", dict(f))\n        record.append(\"FAILURE\", dict(f))\n        body = build_closure_body(\"known_failure\", failures=[f], execution=\"FAILED\",\n                                  adjudication=\"ATTRIBUTED_UNDER_TEST_AUTHORITY\",\n                                  unknowns=[], account_status=\"COMPLETE\")\n        record.append(\"CLOSURE\", body)\n        self._anchor(record)\n        result = validate_record(self.path)\n        self.assertEqual(result[\"account_completeness\"], \"FAIL\")\n        self.assertEqual(result[\"details\"][\"account_completeness\"][\"duplicate_record_failure_ids\"], [\"F-DUP-1\"])\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n\n    # S3\n    def test_s3_duplicate_account_failure_id(self):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"dup_account_id\"})\n        f = make_failure(\"F-DUPACC-1\", \"Account duplicate\", attribution=\"SYSTEM\")\n        record.append(\"FAILURE\", dict(f))\n        body = build_closure_body(\"known_failure\", failures=[f, dict(f)], execution=\"FAILED\",\n                                  adjudication=\"ATTRIBUTED_UNDER_TEST_AUTHORITY\",\n                                  unknowns=[], account_status=\"COMPLETE\")\n        record.append(\"CLOSURE\", body)\n        self._anchor(record)\n        result = validate_record(self.path)\n        self.assertEqual(result[\"account_completeness\"], \"FAIL\")\n        self.assertEqual(result[\"details\"][\"account_completeness\"][\"duplicate_account_failure_ids\"], [\"F-DUPACC-1\"])\n\n    # S4\n    def test_s4_extra_fabricated_account_failure(self):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"extra_account\"})\n        f1 = make_failure(\"F-REAL-1\", \"Real failure\", attribution=\"SYSTEM\")\n        f_fake = make_failure(\"F-FAKE-1\", \"Fabricated failure\", attribution=\"MODEL\")\n        record.append(\"FAILURE\", dict(f1))\n        body = build_closure_body(\"known_failure\", failures=[f1, f_fake], execution=\"FAILED\",\n                                  adjudication=\"ATTRIBUTED_UNDER_TEST_AUTHORITY\",\n                                  unknowns=[], account_status=\"COMPLETE\")\n        record.append(\"CLOSURE\", body)\n        self._anchor(record)\n        result = validate_record(self.path)\n        self.assertEqual(result[\"account_completeness\"], \"FAIL\")\n        self.assertEqual(result[\"details\"][\"account_completeness\"][\"extra_failure_ids\"], [\"F-FAKE-1\"])\n\n    # S5\n    def test_s5_altered_failure_description_or_attribution(self):\n        # Altered description\n        for altered_entry, label in [\n            (make_failure(\"F-ALT-1\", \"Altered description\", attribution=\"SYSTEM\"), \"description\"),\n            (make_failure(\"F-ALT-1\", \"Original description\", attribution=\"MODEL\"), \"attribution\"),\n        ]:\n            with self.subTest(altered=label):\n                path = os.path.join(self.tmp.name, f\"alt_{label}.jsonl\")\n                record = EventRecord(path)\n                record.append(\"RUN_STARTED\", {\"scenario\": \"altered\"})\n                orig = make_failure(\"F-ALT-1\", \"Original description\", attribution=\"SYSTEM\")\n                record.append(\"FAILURE\", dict(orig))\n                body = build_closure_body(\"known_failure\", failures=[altered_entry], execution=\"FAILED\",\n                                          adjudication=\"ATTRIBUTED_UNDER_TEST_AUTHORITY\",\n                                          unknowns=[], account_status=\"COMPLETE\")\n                record.append(\"CLOSURE\", body)\n                write_anchor(record.head_digest, record.length, anchor_path_for(path))\n                result = validate_record(path)\n                self.assertEqual(result[\"account_completeness\"], \"FAIL\")\n                self.assertEqual(result[\"details\"][\"account_completeness\"][\"altered_failure_ids\"], [\"F-ALT-1\"])\n\n    # S6\n    def test_s6_structurally_malformed_event(self):\n        malformed_variants = [\n            ('{\"seq\": 2}', \"missing fields\"),\n            ('{\"seq\": \"2\", \"prev\": \"x\", \"type\": \"STEP\", \"body\": {}, \"digest\": \"abc\"}', \"mistyped seq\"),\n            ('123', \"non-object JSON\"),\n            ('{\"seq\": 2, \"prev\": \"x\", \"type\": \"STEP\", \"digest\": \"abc\"}', \"missing body\"),\n            ('{\"seq\": 2, \"prev\": \"x\", \"body\": {}, \"digest\": \"abc\"}', \"missing type\"),\n        ]\n        for idx, (malformed_line, label) in enumerate(malformed_variants):\n            with self.subTest(variant=label):\n                path = os.path.join(self.tmp.name, f\"mal{idx}.jsonl\")\n                record = EventRecord(path)\n                Runner(record).run(\"normal\")\n                with open(path, encoding=\"utf-8\") as f:\n                    lines = f.readlines()\n                self.assertGreaterEqual(len(lines), 3)\n                lines[1] = malformed_line + \"\\n\"\n                with open(path, \"w\", encoding=\"utf-8\") as f:\n                    f.writelines(lines)\n                # Must not crash; structured FAIL\n                result = validate_record(path)\n                self.assertEqual(result[\"chain_validity\"], \"FAIL\")\n                # C4: terminal explicitly accounts for parse failure\n                self.assertEqual(result[\"terminal_record\"], \"FAIL\")\n                self.assertIn(\"parse\", result[\"details\"][\"terminal_record\"][\"reason\"].lower())\n\n    # S7\n    def test_s7_corrupted_record_reopened_for_append(self):\n        record = EventRecord(self.path)\n        record.append(\"RUN_STARTED\", {\"scenario\": \"corrupt_reopen\"})\n        record.append(\"STEP\", {\"n\": 1})\n        record.append(\"STEP\", {\"n\": 2})\n        # Corrupt middle event body, leaving digest stale (chain invalid)\n        with open(self.path, encoding=\"utf-8\") as f:\n            lines = f.readlines()\n        middle = json.loads(lines[1])\n        middle[\"body\"] = {\"n\": 999, \"tampered\": True}\n        lines[1] = json.dumps(middle) + \"\\n\"\n        with open(self.path, \"w\", encoding=\"utf-8\") as f:\n            f.writelines(lines)\n        with open(self.path, encoding=\"utf-8\") as f:\n            before = f.read()\n        with self.assertRaises(ValueError):\n            EventRecord(self.path)\n        # File unchanged -- append was refused, not partially applied\n        with open(self.path, encoding=\"utf-8\") as f:\n            after = f.read()\n        self.assertEqual(before, after)\n\n    # S8 boundary demonstration (C3) -- not a protection claim\n    def test_s8_record_and_anchor_both_rewritten_demonstrates_boundary(self):\n        record = EventRecord(self.path)\n        Runner(record).run(\"normal\")\n        original = record.read_all()\n        # Rewrite record with altered content, re-chained consistently\n        os.remove(self.path)\n        rewritten = EventRecord(self.path)\n        for ev in original:\n            body = ev[\"body\"]\n            if ev[\"type\"] == \"STEP\":\n                body = dict(body, n=999)\n            rewritten.append(ev[\"type\"], body)\n        ok, _ = verify_chain(rewritten.read_all())\n        self.assertTrue(ok)\n        # AND rewrite the anchor to match the rewritten head (coordinated rewrite)\n        write_anchor(rewritten.head_digest, rewritten.length, anchor_path_for(self.path))\n        result = validate_record(self.path)\n        # Boundary demonstrated: coordinated record+anchor rewrite is NOT\n        # detected by the current Stage 1 anchor. This documents the\n        # limitation recorded for C3; it is not a pass of a protection claim.\n        self.assertEqual(result[\"chain_validity\"], \"PASS\")\n        self.assertEqual(result[\"terminal_record\"], \"PASS\")\n        self.assertEqual(result[\"account_completeness\"], \"PASS\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 }
}''')

def main():
    tmp = Path(tempfile.mkdtemp(prefix='duenna-stage1-'))
    print(f'materialised into: {tmp}')
    for rel, entry in PAYLOAD.items():
        dest = tmp / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(entry['text'], encoding='utf-8')
        digest = hashlib.sha256(entry['text'].encode()).hexdigest()
        match = 'MATCH' if digest == entry['sha256'] else 'MISMATCH'
        print(f'  {rel:45s} sha256 {digest[:16]}... {match}')
    proc = subprocess.run(
        [sys.executable, '-m', 'unittest', 'discover', '-s', 'tests', '-v'],
        cwd=tmp, capture_output=True, text=True)
    sys.stdout.write(proc.stdout)
    sys.stderr.write(proc.stderr)
    print(f'INDEPENDENT RUN EXIT CODE: {proc.returncode}')
    return proc.returncode

if __name__ == '__main__':
    raise SystemExit(main())
